import { Component } from '../component';
import { createElement, createVNode, Fragment } from '../create-element';
import { EMPTY_OBJ, EMPTY_ARR } from '../constants';
import { assign, removeNode } from '../util';
import {
	setStyle,
	eventProxy,
	eventProxyCapture,
	invokeDiffHook,
	invokeRenderHook,
	invokeDiffedHook,
	invokeCatchError,
	invokeCommitHook,
	invokeUnmountHook,
	invokeRootHook
} from './props';

const IS_HYDRATE = EMPTY_OBJ;

class Coordinator {
	constructor() {}

	diffChildren(
		parentDom,
		renderResult,
		newParentVNode,
		oldParentVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating
	) {
		this.recordChildPass(newParentVNode, oldParentVNode, 0);
		let i, j, oldVNode, childVNode, newDom, firstChildDom, refs;

		// This is a compression of oldParentVNode!=null && oldParentVNode != EMPTY_OBJ && oldParentVNode._children || EMPTY_ARR
		// as EMPTY_OBJ._children should be `undefined`.
		let oldChildren = (oldParentVNode && oldParentVNode._children) || EMPTY_ARR;

		let oldChildrenLength = oldChildren.length;

		// Only in very specific places should this logic be invoked (top level `render` and `diffElementNodes`).
		// I'm using `EMPTY_OBJ` to signal when `diffChildren` is invoked in these situations. I can't use `null`
		// for this purpose, because `null` is a valid value for `oldDom` which can mean to skip to this logic
		// (e.g. if mounting a new tree in which the old DOM should be ignored (usually for Fragments).
		if (oldDom == EMPTY_OBJ) {
			if (excessDomChildren != null) {
				oldDom = excessDomChildren[0];
			} else if (oldChildrenLength) {
				oldDom = this.getDomSibling(oldParentVNode, 0);
			} else {
				oldDom = null;
			}
		}

		newParentVNode._children = [];
		for (i = 0; i < renderResult.length; i++) {
			childVNode = renderResult[i];

			if (childVNode == null || typeof childVNode == 'boolean') {
				childVNode = newParentVNode._children[i] = null;
			}
			// If this newVNode is being reused (e.g. <div>{reuse}{reuse}</div>) in the same diff,
			// or we are rendering a component (e.g. setState) copy the oldVNodes so it can have
			// it's own DOM & etc. pointers
			else if (typeof childVNode == 'string' || typeof childVNode == 'number') {
				childVNode = newParentVNode._children[i] = createVNode(
					null,
					childVNode,
					null,
					null,
					childVNode
				);
			} else if (Array.isArray(childVNode)) {
				childVNode = newParentVNode._children[i] = createVNode(
					Fragment,
					{ children: childVNode },
					null,
					null,
					null
				);
			} else if (childVNode._depth > 0) {
				// VNode is already in use, clone it. This can happen in the following
				// scenario:
				//   const reuse = <div />
				//   <div>{reuse}<span />{reuse}</div>
				childVNode = newParentVNode._children[i] = createVNode(
					childVNode.type,
					childVNode.props,
					childVNode.key,
					null,
					childVNode._original
				);
			} else {
				childVNode = newParentVNode._children[i] = childVNode;
			}

			// Terser removes the `continue` here and wraps the loop body
			// in a `if (childVNode) { ... } condition
			if (childVNode == null) {
				continue;
			}

			childVNode._parent = newParentVNode;
			childVNode._depth = newParentVNode._depth + 1;

			// Check if we find a corresponding element in oldChildren.
			// If found, delete the array item by setting to `undefined`.
			// We use `undefined`, as `null` is reserved for empty placeholders
			// (holes).
			oldVNode = oldChildren[i];

			if (
				oldVNode === null ||
				(oldVNode &&
					childVNode.key == oldVNode.key &&
					childVNode.type === oldVNode.type)
			) {
				oldChildren[i] = undefined;
			} else {
				// Either oldVNode === undefined or oldChildrenLength > 0,
				// so after this loop oldVNode == null or oldVNode is a valid value.
				for (j = 0; j < oldChildrenLength; j++) {
					oldVNode = oldChildren[j];
					// If childVNode is unkeyed, we only match similarly unkeyed nodes, otherwise we match by key.
					// We always match by type (in either case).
					if (
						oldVNode &&
						childVNode.key == oldVNode.key &&
						childVNode.type === oldVNode.type
					) {
						oldChildren[j] = undefined;
						break;
					}
					oldVNode = null;
				}
			}

			oldVNode = oldVNode || EMPTY_OBJ;

			// Morph the old element into the new one, but don't append it to the dom yet
			this.diff(
				parentDom,
				childVNode,
				oldVNode,
				globalContext,
				isSvg,
				excessDomChildren,
				commitQueue,
				oldDom,
				isHydrating
			);

			newDom = childVNode._dom;

			if ((j = childVNode.ref) && oldVNode.ref != j) {
				if (!refs) refs = [];
				if (oldVNode.ref) refs.push(oldVNode.ref, null, childVNode);
				refs.push(j, childVNode._component || newDom, childVNode);
			}

			if (newDom != null) {
				if (firstChildDom == null) {
					firstChildDom = newDom;
				}

				if (
					typeof childVNode.type == 'function' &&
					childVNode._children === oldVNode._children
				) {
					childVNode._nextDom = oldDom = this.reorderChildren(
						childVNode,
						oldDom,
						parentDom
					);
				} else {
					oldDom = this.placeChild(
						parentDom,
						childVNode,
						oldVNode,
						oldChildren,
						excessDomChildren,
						newDom,
						oldDom
					);
				}

				// Browsers will infer an option's `value` from `textContent` when
				// no value is present. This essentially bypasses our code to set it
				// later in `diff()`. It works fine in all browsers except for IE11
				// where it breaks setting `select.value`. There it will be always set
				// to an empty string. Re-applying an options value will fix that, so
				// there are probably some internal data structures that aren't
				// updated properly.
				//
				// To fix it we make sure to reset the inferred value, so that our own
				// value check in `diff()` won't be skipped.
				if (!isHydrating && newParentVNode.type === 'option') {
					// @ts-ignore We have validated that the type of parentDOM is 'option'
					// in the above check
					parentDom.value = '';
				} else if (typeof newParentVNode.type == 'function') {
					// Because the newParentVNode is Fragment-like, we need to set it's
					// _nextDom property to the nextSibling of its last child DOM node.
					//
					// `oldDom` contains the correct value here because if the last child
					// is a Fragment-like, then oldDom has already been set to that child's _nextDom.
					// If the last child is a DOM VNode, then oldDom will be set to that DOM
					// node's nextSibling.
					newParentVNode._nextDom = oldDom;
				}
			} else if (
				oldDom &&
				oldVNode._dom == oldDom &&
				oldDom.parentNode != parentDom
			) {
				// The above condition is to handle null placeholders. See test in placeholder.test.js:
				// `efficiently replace null placeholders in parent rerenders`
				oldDom = this.getDomSibling(oldVNode);
			}
		}

		newParentVNode._dom = firstChildDom;

		// Remove children that are not part of any vnode.
		if (excessDomChildren != null && typeof newParentVNode.type != 'function') {
			for (i = excessDomChildren.length; i--; ) {
				if (excessDomChildren[i] != null) removeNode(excessDomChildren[i]);
			}
		}

		// Remove remaining oldChildren if there are any.
		for (i = oldChildrenLength; i--; ) {
			if (oldChildren[i] != null) {
				if (
					typeof newParentVNode.type == 'function' &&
					oldChildren[i]._dom != null &&
					oldChildren[i]._dom == newParentVNode._nextDom
				) {
					// If the newParentVNode.__nextDom points to a dom node that is about to
					// be unmounted, then get the next sibling of that vnode and set
					// _nextDom to it
					newParentVNode._nextDom = this.getDomSibling(oldParentVNode, i + 1);
				}

				this.unmount(oldChildren[i], oldChildren[i]);
			}
		}

		// Set refs only after unmount
		if (refs) {
			for (i = 0; i < refs.length; i++) {
				this.applyRef(refs[i], refs[++i], refs[++i]);
			}
		}
	}

	reorderChildren(childVNode, oldDom, parentDom) {
		this.recordChildPass(childVNode, childVNode, 0);
		for (let tmp = 0; tmp < childVNode._children.length; tmp++) {
			let vnode = childVNode._children[tmp];
			if (vnode) {
				vnode._parent = childVNode;

				if (typeof vnode.type == 'function') {
					this.reorderChildren(vnode, oldDom, parentDom);
				} else {
					oldDom = this.placeChild(
						parentDom,
						vnode,
						vnode,
						childVNode._children,
						null,
						vnode._dom,
						oldDom
					);
				}
			}
		}

		return oldDom;
	}

	toChildArray(children, out) {
		out = out || [];
		if (children == null || typeof children == 'boolean') {
		} else if (Array.isArray(children)) {
			children.some(child => {
				this.toChildArray(child, out);
			});
		} else {
			out.push(children);
		}
		return out;
	}

	placeChild(
		parentDom,
		childVNode,
		oldVNode,
		oldChildren,
		excessDomChildren,
		newDom,
		oldDom
	) {
		let nextDom;
		if (childVNode._nextDom !== undefined) {
			// Only Fragments or components that return Fragment like VNodes will
			// have a non-undefined _nextDom. Continue the diff from the sibling
			// of last DOM child of this child VNode
			nextDom = childVNode._nextDom;

			// Eagerly cleanup _nextDom. We don't need to persist the value because
			// it is only used by `diffChildren` to determine where to resume the diff after
			// diffing Components and Fragments. Once we store it the nextDOM local var, we
			// can clean up the property
			childVNode._nextDom = undefined;
		} else if (
			excessDomChildren == oldVNode ||
			newDom != oldDom ||
			newDom.parentNode == null
		) {
			// NOTE: excessDomChildren==oldVNode above:
			// This is a compression of excessDomChildren==null && oldVNode==null!
			// The values only have the same type when `null`.

			outer: if (oldDom == null || oldDom.parentNode !== parentDom) {
				parentDom.appendChild(newDom);
				nextDom = null;
			} else {
				// `j<oldChildrenLength; j+=2` is an alternative to `j++<oldChildrenLength/2`
				for (
					let sibDom = oldDom, j = 0;
					(sibDom = sibDom.nextSibling) && j < oldChildren.length;
					j += 2
				) {
					if (sibDom == newDom) {
						break outer;
					}
				}
				parentDom.insertBefore(newDom, oldDom);
				nextDom = oldDom;
			}
		}

		// If we have pre-calculated the nextDOM node, use it. Else calculate it now
		// Strictly check for `undefined` here cuz `null` is a valid value of `nextDom`.
		// See more detail in create-element.js:createVNode
		if (nextDom !== undefined) {
			oldDom = nextDom;
		} else {
			oldDom = newDom.nextSibling;
		}

		return oldDom;
	}

	diff(
		parentDom,
		newVNode,
		oldVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating
	) {
		let tmp,
			newType = newVNode.type;

		// When passing through createElement it assigns the object
		// constructor as undefined. This to prevent JSON-injection.
		if (newVNode.constructor !== undefined) return null;

		// If the previous diff bailed out, resume creating/hydrating.
		if (oldVNode._hydrating != null) {
			isHydrating = oldVNode._hydrating;
			oldDom = newVNode._dom = oldVNode._dom;
			// if we resume, we want the tree to be "unlocked"
			newVNode._hydrating = null;
			excessDomChildren = [oldDom];
		}

		invokeDiffHook(newVNode);

		try {
			outer: if (typeof newType == 'function') {
				let c, isNew, oldProps, oldState, snapshot, clearProcessingException;
				let newProps = newVNode.props;

				// Necessary for createContext api. Setting this property will pass
				// the context value as `this.context` just for this component.
				tmp = newType.contextType;
				let provider = tmp && globalContext[tmp._id];
				let componentContext = tmp
					? provider
						? provider.props.value
						: tmp._defaultValue
					: globalContext;

				// Get component and set it to `c`
				if (oldVNode._component) {
					c = newVNode._component = oldVNode._component;
					clearProcessingException = c._processingException = c._pendingError;
				} else {
					// Instantiate the new component
					if ('prototype' in newType && newType.prototype.render) {
						// @ts-ignore The check above verifies that newType is suppose to be constructed
						newVNode._component = c = new newType(newProps, componentContext); // eslint-disable-line new-cap
					} else {
						// @ts-ignore Trust me, Component implements the interface we want
						newVNode._component = c = new Component(newProps, componentContext);
						c.constructor = newType;
						c.render = doRender;
					}
					if (provider) provider.sub(c);

					c.props = newProps;
					if (!c.state) c.state = {};
					c.context = componentContext;
					c._globalContext = globalContext;
					isNew = c._dirty = true;
					c._renderCallbacks = [];
				}

				// Invoke getDerivedStateFromProps
				if (c._nextState == null) {
					c._nextState = c.state;
				}
				if (newType.getDerivedStateFromProps != null) {
					if (c._nextState == c.state) {
						c._nextState = assign({}, c._nextState);
					}

					assign(
						c._nextState,
						newType.getDerivedStateFromProps(newProps, c._nextState)
					);
				}

				oldProps = c.props;
				oldState = c.state;

				// Invoke pre-render lifecycle methods
				if (isNew) {
					if (
						newType.getDerivedStateFromProps == null &&
						c.componentWillMount != null
					) {
						c.componentWillMount();
					}

					if (c.componentDidMount != null) {
						c._renderCallbacks.push(c.componentDidMount);
					}
				} else {
					if (
						newType.getDerivedStateFromProps == null &&
						newProps !== oldProps &&
						c.componentWillReceiveProps != null
					) {
						c.componentWillReceiveProps(newProps, componentContext);
					}

					if (
						(!c._force &&
							c.shouldComponentUpdate != null &&
							c.shouldComponentUpdate(
								newProps,
								c._nextState,
								componentContext
							) === false) ||
						newVNode._original === oldVNode._original
					) {
						c.props = newProps;
						c.state = c._nextState;
						// More info about this here: https://gist.github.com/JoviDeCroock/bec5f2ce93544d2e6070ef8e0036e4e8
						if (newVNode._original !== oldVNode._original) c._dirty = false;
						c._vnode = newVNode;
						newVNode._dom = oldVNode._dom;
						newVNode._children = oldVNode._children;
						if (c._renderCallbacks.length) {
							commitQueue.push(c);
						}

						break outer;
					}

					if (c.componentWillUpdate != null) {
						c.componentWillUpdate(newProps, c._nextState, componentContext);
					}

					if (c.componentDidUpdate != null) {
						c._renderCallbacks.push(() => {
							c.componentDidUpdate(oldProps, oldState, snapshot);
						});
					}
				}

				c.context = componentContext;
				c.props = newProps;
				c.state = c._nextState;

				invokeRenderHook(newVNode);

				c._dirty = false;
				c._vnode = newVNode;
				c._parentDom = parentDom;

				tmp = c.render(c.props, c.state, c.context);

				// Handle setState called in render, see #2553
				c.state = c._nextState;

				if (c.getChildContext != null) {
					globalContext = assign(assign({}, globalContext), c.getChildContext());
				}

				if (!isNew && c.getSnapshotBeforeUpdate != null) {
					snapshot = c.getSnapshotBeforeUpdate(oldProps, oldState);
				}

				let isTopLevelFragment =
					tmp != null && tmp.type === Fragment && tmp.key == null;
				let renderResult = isTopLevelFragment ? tmp.props.children : tmp;

				this.diffChildren(
					parentDom,
					Array.isArray(renderResult) ? renderResult : [renderResult],
					newVNode,
					oldVNode,
					globalContext,
					isSvg,
					excessDomChildren,
					commitQueue,
					oldDom,
					isHydrating
				);

				c.base = newVNode._dom;

				// We successfully rendered this VNode, unset any stored hydration/bailout state:
				newVNode._hydrating = null;

				if (c._renderCallbacks.length) {
					commitQueue.push(c);
				}

				if (clearProcessingException) {
					c._pendingError = c._processingException = null;
				}

				c._force = false;
			} else if (
				excessDomChildren == null &&
				newVNode._original === oldVNode._original
			) {
				newVNode._children = oldVNode._children;
				newVNode._dom = oldVNode._dom;
			} else {
				newVNode._dom = this.diffElementNodes(
					oldVNode._dom,
					newVNode,
					oldVNode,
					globalContext,
					isSvg,
					excessDomChildren,
					commitQueue,
					isHydrating
				);
			}

			invokeDiffedHook(newVNode);
		} catch (e) {
			newVNode._original = null;
			// if hydrating or creating initial tree, bailout preserves DOM:
			if (isHydrating || excessDomChildren != null) {
				newVNode._dom = oldDom;
				newVNode._hydrating = !!isHydrating;
				excessDomChildren[excessDomChildren.indexOf(oldDom)] = null;
				// ^ could possibly be simplified to:
				// excessDomChildren.length = 0;
			}
			invokeCatchError(e, newVNode, oldVNode);
		}
	}

	commitRoot(commitQueue, root) {
		invokeCommitHook(root, commitQueue);

		commitQueue.some(c => {
			try {
				// @ts-ignore Reuse the commitQueue variable here so the type changes
				commitQueue = c._renderCallbacks;
				c._renderCallbacks = [];
				commitQueue.some(cb => {
					// @ts-ignore See above ts-ignore on commitQueue
					cb.call(c);
				});
			} catch (e) {
				invokeCatchError(e, c._vnode);
			}
		});
	}

	diffElementNodes(
		dom,
		newVNode,
		oldVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		isHydrating
	) {
		this.recordChildPass(newVNode, oldVNode, 0);
		let i;
		let oldProps = oldVNode.props;
		let newProps = newVNode.props;

		// Tracks entering and exiting SVG namespace when descending through the tree.
		isSvg = newVNode.type === 'svg' || isSvg;

		if (excessDomChildren != null) {
			for (i = 0; i < excessDomChildren.length; i++) {
				const child = excessDomChildren[i];

				// if newVNode matches an element in excessDomChildren or the `dom`
				// argument matches an element in excessDomChildren, remove it from
				// excessDomChildren so it isn't later removed in diffChildren
				if (
					child != null &&
					((newVNode.type === null
						? child.nodeType === 3
						: child.localName === newVNode.type) ||
						dom == child)
				) {
					dom = child;
					excessDomChildren[i] = null;
					break;
				}
			}
		}

		if (dom == null) {
			if (newVNode.type === null) {
				// @ts-ignore createTextNode returns Text, we expect PreactElement
				return document.createTextNode(newProps);
			}

			if (isSvg) {
				dom = document.createElementNS(
					'http://www.w3.org/2000/svg',
					// @ts-ignore We know `newVNode.type` is a string
					newVNode.type
				);
			} else {
				dom = document.createElement(
					// @ts-ignore We know `newVNode.type` is a string
					newVNode.type,
					newProps.is && { is: newProps.is }
				);
			}

			// we created a new parent, so none of the previously attached children can be reused:
			excessDomChildren = null;
			// we are creating a new node, so we can assume this is a new subtree (in case we are hydrating), this deopts the hydrate
			isHydrating = false;
		}

		if (newVNode.type === null) {
			// During hydration, we still have to split merged text from SSR'd HTML.
			if (oldProps !== newProps && (!isHydrating || dom.data !== newProps)) {
				dom.data = newProps;
			}
		} else {
			if (excessDomChildren != null) {
				excessDomChildren = EMPTY_ARR.slice.call(dom.childNodes);
			}

			oldProps = oldVNode.props || EMPTY_OBJ;

			let oldHtml = oldProps.dangerouslySetInnerHTML;
			let newHtml = newProps.dangerouslySetInnerHTML;

			// During hydration, props are not diffed at all (including dangerouslySetInnerHTML)
			// @TODO we should warn in debug mode when props don't match here.
			if (!isHydrating) {
				// But, if we are in a situation where we are using existing DOM (e.g. replaceNode)
				// we should read the existing DOM attributes to diff them
				if (excessDomChildren != null) {
					oldProps = {};
					for (let i = 0; i < dom.attributes.length; i++) {
						oldProps[dom.attributes[i].name] = dom.attributes[i].value;
					}
				}

				if (newHtml || oldHtml) {
					// Avoid re-applying the same '__html' if it did not changed between re-render
					if (
						!newHtml ||
						((!oldHtml || newHtml.__html != oldHtml.__html) &&
							newHtml.__html !== dom.innerHTML)
					) {
						dom.innerHTML = (newHtml && newHtml.__html) || '';
					}
				}
			}

			this.diffProps(dom, newProps, oldProps, isSvg, isHydrating);

			// If the new vnode didn't have dangerouslySetInnerHTML, diff its children
			if (newHtml) {
				newVNode._children = [];
			} else {
				i = newVNode.props.children;
				this.diffChildren(
					dom,
					Array.isArray(i) ? i : [i],
					newVNode,
					oldVNode,
					globalContext,
					newVNode.type === 'foreignObject' ? false : isSvg,
					excessDomChildren,
					commitQueue,
					EMPTY_OBJ,
					isHydrating
				);
			}

			// (as above, don't diff props during hydration)
			if (!isHydrating) {
				if (
					'value' in newProps &&
					(i = newProps.value) !== undefined &&
